<!doctype html><html><head><meta charset="utf-8"><title>Deposit Review</title></head><body><h1>Deposit Review</h1><p>Independently verify blockchain, destination address, network, amount, and confirmations before approving. Submitted hashes alone are NOT proof of payment.</p>@if(session('status'))<p>{{ session('status') }}</p>@endif @if($errors->any())<ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<table border="1"><tr><th>ID</th><th>Member</th><th>Amount</th><th>Network</th><th>Hash</th><th>Status</th><th>Actions</th></tr>@foreach($deposits as $d)<tr><td>{{ $d->id }}</td><td>{{ $d->user_id }}</td><td>{{ $d->amount }}</td><td>{{ $d->network }}</td><td>{{ $d->tx_hash }}</td><td>{{ $d->status }}</td><td>@if($d->status==='pending')<form method="post" action="{{ route('admin.deposit-review.approve',$d->id) }}">@csrf<input name="verification_reference" placeholder="Independent verification reference" required><button>Approve verified</button></form><form method="post" action="{{ route('admin.deposit-review.reject',$d->id) }}">@csrf<button>Reject</button></form>@endif</td></tr>@endforeach</table></body></html>
